static bool HandleNpcAddCommand(ChatHandler* handler, const char* args)
{
    if (!*args)
        return false;

    char* charID = handler->extractKeyFromLink((char*)args, "Hcreature_entry");
    if (!charID)
        return false;

    char* team = strtok(NULL, " ");
    int32 teamval = 0;
    uint32 id;
    if (!Trinity::ParseCommandInteger(charID, id) || !id ||
        (team && !Trinity::ParseCommandInteger(team, teamval)))
        return false;
    if (teamval < 0)
        teamval = 0;
    if (!sObjectMgr->GetCreatureTemplate(id))
    {
        handler->PSendSysMessage(LANG_COMMAND_INVALIDCREATUREID, id);
        handler->SetSentErrorMessage(true);
        return false;
    }

    Player* chr = handler->GetSession()->GetPlayer();
    float x = chr->GetPositionX();
    float y = chr->GetPositionY();
    float z = chr->GetPositionZ();
    float o = chr->GetOrientation();
    Map* map = chr->GetMap();

    if (Transport* trans = chr->GetTransport())
    {
        ObjectGuid::LowType guid = sObjectMgr->GetGenerator<HighGuid::Creature>()->Generate();
        CreatureData& data = sObjectMgr->NewOrExistCreatureData(guid);
        data.id = id;
        data.phaseMask = chr->GetPhaseMask();
        data.posX = chr->GetTransOffsetX();
        data.posY = chr->GetTransOffsetY();
        data.posZ = chr->GetTransOffsetZ();
        data.orientation = chr->GetTransOffsetO();

        Creature* creature = trans->CreateNPCPassenger(guid, &data);
        if (!creature)
        {
            sObjectMgr->DeleteCreatureData(guid);
            handler->SendSysMessage("NPC passenger creation failed; the new spawn was not saved.");
            handler->SetSentErrorMessage(true);
            return false;
        }

        creature->SaveToDB(trans->GetGOInfo()->moTransport.SpawnMap, UI64LIT(1) << map->GetSpawnMode(), chr->GetPhaseMask());

        sObjectMgr->AddCreatureToGrid(guid, &data);
        return true;
    }

    Creature* creature = new Creature();
    if (!creature->Create(sObjectMgr->GetGenerator<HighGuid::Creature>()->Generate(), map, chr->GetPhaseMgr().GetPhaseMaskForSpawn(), id, 0, (uint32)teamval, x, y, z, o))
    {
        delete creature;
        return false;
    }

    creature->SaveToDB(map->GetId(), (UI64LIT(1) << map->GetSpawnMode()), chr->GetPhaseMgr().GetPhaseMaskForSpawn());

    ObjectGuid::LowType db_guid = creature->GetDBTableGUIDLow();

    // To call _LoadGoods(); _LoadQuests(); CreateTrainerSpells();
    // current "creature" variable is deleted and created fresh new, otherwise old values might trigger asserts or cause undefined behavior
    creature->CleanupsBeforeDelete();
    delete creature;
    creature = new Creature();
    if (!creature->LoadCreatureFromDB(db_guid, map))
    {
        delete creature;
        return false;
    }

    sObjectMgr->AddCreatureToGrid(db_guid, sObjectMgr->GetCreatureData(db_guid));
    return true;
}
